#!/usr/bin/env python3
from pathlib import Path
import math,re
root=Path(__file__).resolve().parents[1];build=root/'build'
def text(n):
 p=build/n;return p.read_text(errors='ignore') if p.exists() else ''
def val(p,d):
 m=re.search(p,d);return float(m.group(1)) if m else None
def mapped(b):
 d=text(f'{b}-mapped-stat.txt');c=val(r'\n\s*(\d+)\s+[0-9.E+]+ cells',d);a=val(r'Chip area.*?:\s*([0-9.]+)',d);s=val(r'sequential elements:\s*([0-9.]+)',d);return c,a,s,(a-s if a is not None and s is not None else None)
def timing(b):
 s=val(r'worst slack max\s+([0-9.-]+)',text(f'{b}-sta.txt'));return s,(1000/(10-s) if s is not None else None)
fmt=lambda x,d=3:'—' if x is None else f'{x:.{d}f}'
dual=re.search(r'mode=\s*dual.*?c0_cycles=(\d+).*?c1_cycles=(\d+).*?c0_retired=(\d+).*?c1_retired=(\d+).*?BusRd=(\d+).*?BusRdX=(\d+).*?BusUpgr=(\d+).*?hits=(\d+).*?misses=(\d+).*?writebacks=(\d+).*?invalidations=(\d+).*?M=(\d+).*?E=(\d+).*?S=(\d+).*?I=(\d+)',text('parallel_sum.log'))
single=re.search(r'mode=single.*?c0_cycles=(\d+).*?c0_retired=(\d+)',text('single_sum.log'))
producer=re.search(r'result=(\d+).*?c0_cycles=(\d+).*?c1_cycles=(\d+).*?c0_retired=(\d+).*?c1_retired=(\d+).*?BusRd=(\d+).*?BusRdX=(\d+).*?BusUpgr=(\d+).*?hits=(\d+).*?misses=(\d+).*?writebacks=(\d+).*?invalidations=(\d+)',text('producer_consumer.log'))
shared_counter=re.search(r'result=(\d+).*?c0_cycles=(\d+).*?c1_cycles=(\d+).*?c0_retired=(\d+).*?c1_retired=(\d+).*?BusRd=(\d+).*?BusRdX=(\d+).*?BusUpgr=(\d+).*?hits=(\d+).*?misses=(\d+).*?writebacks=(\d+).*?invalidations=(\d+)',text('shared_counter.log'))
false_sharing=re.search(r'MEASURE false_sharing invalidations=(\d+) bus_transactions=(\d+)',text('coherence.log'))
capacity=re.findall(r'cache_capacity size=(\d+) line=(\d+) working=(\d+) cycles=(\d+) hits=(\d+) misses=(\d+) miss_rate_ppm=(\d+)',text('cache-sweep.log'))
dcache_configs=re.findall(r'PASS coherence cache=(\d+) random=(\d+) litmus=(\d+) BusRd=(\d+) BusRdX=(\d+) BusUpgr=(\d+) invalidations=(\d+) hits=(\d+) misses=(\d+) writebacks=(\d+) cycles=(\d+)',text('cache-sweep.log'))
longrun=re.search(r'cache=(\d+) random=(\d+) litmus=(\d+).*?BusRd=(\d+).*?BusRdX=(\d+).*?BusUpgr=(\d+).*?invalidations=(\d+).*?hits=(\d+).*?misses=(\d+).*?writebacks=(\d+)',text('coherence-long.log'))
missing=[]
for name,value in [('dual parallel sum',dual),('single parallel sum',single),('producer/consumer',producer),('shared counter',shared_counter),('false sharing',false_sharing),('100k random run',longrun)]:
 if value is None:missing.append(name)
if len(dcache_configs)!=4:missing.append(f'four D-cache configurations (found {len(dcache_configs)})')
if len(capacity)<7:missing.append(f'seven capacity/line functional configurations (found {len(capacity)})')
for block in ('core','dcache','mesi','soc'):
 if any(x is None for x in mapped(block)) or timing(block)[0] is None:missing.append(f'{block} mapping/STA')
for size in (512,1024,2048,4096):
 if mapped(f'dcache-{size}')[1] is None or timing(f'dcache-{size}')[0] is None:missing.append(f'{size}-byte D-cache mapping/STA')
if missing:raise SystemExit('missing required measured V1 evidence: '+', '.join(missing))
L=['# Measured V1 results','','Generated by `scripts/benchmark.py` exclusively from simulator, Yosys, and OpenSTA logs.','','## Multicore benchmarks','','| Workload | Cycles | Retired | CPI | L1 miss rate | Invalidations | Bus traffic |','|---|---:|---:|---:|---:|---:|---:|']
workload_rows=[];workload_notes=[]
if dual:
 v=list(map(int,dual.groups()));cy=max(v[0],v[1]);ret=v[2]+v[3];workload_rows.append(f'| Parallel sum (dual) | {cy} | {ret} | {cy/ret:.3f} | {v[8]/(v[7]+v[8]):.2%} | {v[10]} | {v[4]+v[5]+v[6]} |');workload_notes.append(f'MESI line-cycle occupancy: M={v[11]}, E={v[12]}, S={v[13]}, I={v[14]}.')
if single:
 s=list(map(int,single.groups()));workload_rows.append(f'| Parallel sum (single) | {s[0]} | {s[1]} | {s[0]/s[1]:.3f} | — | — | — |')
 if dual:workload_notes.append(f'Measured speedup: {s[0]}/{max(v[0],v[1])} = **{s[0]/max(v[0],v[1]):.3f}×**.')
if producer:
 p=list(map(int,producer.groups()));ret=p[3]+p[4];workload_rows.append(f'| Producer/consumer | {max(p[1],p[2])} | {ret} | {max(p[1],p[2])/ret:.3f} | {p[9]/(p[8]+p[9]):.2%} | {p[11]} | {p[5]+p[6]+p[7]} |')
if shared_counter:
 p=list(map(int,shared_counter.groups()));ret=p[3]+p[4];workload_rows.append(f'| Shared counter | {max(p[1],p[2])} | {ret} | {max(p[1],p[2])/ret:.3f} | {p[9]/(p[8]+p[9]):.2%} | {p[11]} | {p[5]+p[6]+p[7]} |')
if false_sharing:
 f=list(map(int,false_sharing.groups()));workload_rows.append(f'| False sharing (directed) | — | — | — | — | {f[0]} | {f[1]} |')
L+=workload_rows+['']+workload_notes
L+=['','## Cache configuration sweep','','The I-cache microbenchmark uses two passes over a 4 KiB working set to distinguish capacity and line-size effects.','','| I-cache | Line | Working set | Cycles | Hits | Misses | Miss rate |','|---:|---:|---:|---:|---:|---:|---:|']
seen=set()
for row in capacity:
 x=tuple(map(int,row));key=(x[0],x[1])
 if key in seen:continue
 seen.add(key);L.append(f'| {x[0]} B | {x[1]} B | {x[2]} B | {x[3]} | {x[4]} | {x[5]} | {x[6]/10000:.2f}% |')
L+=['','The following table unifies performance, area, and timing for the same direct-mapped D-cache RTL and the same directed-plus-random coherence workload.','','| D-cache | Cycles | Hits | Misses | Miss rate | Invalidations | Area µm² | Critical period ns |','|---:|---:|---:|---:|---:|---:|---:|---:|']
for row in dcache_configs:
 x=list(map(int,row));size=x[0];_,area,_,_=mapped(f'dcache-{size}');sl,_=timing(f'dcache-{size}');period=None if sl is None else 10-sl
 L.append(f'| {size} B | {x[10]} | {x[7]} | {x[8]} | {x[8]/(x[7]+x[8]):.2%} | {x[6]} | {fmt(area)} | {fmt(period,2)} |')
if longrun:
 r=list(map(int,longrun.groups()));L+=['',f'Long random run: {r[1]:,} operations + {r[2]} litmus interleavings, {r[6]:,} invalidations, {r[3]+r[4]+r[5]:,} bus transactions, all checks passed.']
L+=['','## Standard-cell synthesis and STA','','Nangate45 typical cells, 10 ns ideal clock, 0.2 ns I/O delay, no wire parasitics. Shared SRAMs are black-box macros; cache arrays are intentionally flops.','','| Block | Cells | Total area µm² | Sequential | Combinational | Slack ns | Fmax MHz |','|---|---:|---:|---:|---:|---:|---:|']
for b,label in [('core','RV32I core'),('dcache','1 KiB D-cache'),('mesi','MESI controller'),('soc','Dual-core SoC logic')]:
 c,a,s,comb=mapped(b);sl,f=timing(b);L.append(f'| {label} | {"—" if c is None else f"{int(c):,}"} | {fmt(a)} | {fmt(s)} | {fmt(comb)} | {fmt(sl,2)} | {fmt(f,2)} |')
L+=['','### D-cache area/timing scaling','','| Capacity | Cells | Area µm² | Critical period ns | Fmax MHz |','|---:|---:|---:|---:|---:|']
for size in (512,1024,2048,4096):
 d=text(f'dcache-{size}-mapped-stat.txt');t=text(f'dcache-{size}-sta.txt');c=val(r'\n\s*(\d+)\s+[0-9.E+]+ cells',d);a=val(r'Chip area.*?:\s*([0-9.]+)',d);sl=val(r'worst slack max\s+([0-9.-]+)',t);period=10-sl if sl is not None else None;L.append(f'| {size} B | {"—" if c is None else f"{int(c):,}"} | {fmt(a)} | {fmt(period,2)} | {fmt(1000/period if period else None,3)} |')
bd=val(r'worst slack max\s+([0-9.-]+)',text('dcache-before-occupancy-opt-sta.txt'));ad=val(r'worst slack max\s+([0-9.-]+)',text('dcache-sta.txt'))
if bd is None or ad is None:raise SystemExit('missing required behavior-equivalent D-cache before/after STA evidence')
before_period=10-bd;after_period=10-ad
if not all(math.isfinite(x) and x>0 for x in (before_period,after_period)) or after_period>=before_period:
 raise SystemExit(f'D-cache occupancy optimization did not improve timing: {before_period:.2f} -> {after_period:.2f} ns')
L+=['','## Critical-path optimization evidence','']
L.append(f'- Behavior-equivalent MESI occupancy implementation (`LEGACY_COUNTONES_OCCUPANCY` passes the same D-cache test): critical period {before_period:.2f} → {after_period:.2f} ns ({(1-after_period/before_period)*100:.1f}% reduction).')
L+=['','Negative cache/SoC slack is retained to demonstrate why production caches use SRAM macros and why these pre-layout values are not signoff.']
(root/'docs'/'results.md').write_text('\n'.join(L)+'\n');print(root/'docs'/'results.md')
